":0,"kind":"aitalk","tag":"speak","payload":{"tag":"speak","k":"aitalk","situation":"양말 가게에서 값을 물어봐요","role":"점원 (Clerk)","open":"Hello! May I help you?","turns":3,"script":[{"ai":"They're two thousand won."},{"ai":"They're fifty thousand won."},{"ai":"You're welcome!"}],"hints":["Yes, please. How much are these socks?","How much are these shoes?","Thank you."]}},{"lesson":6,"pos":7,"n":1,"kind":"aitalk","tag":"speak","payload":{"tag":"speak","k":"aitalk","situation":"선글라스 가게에서 값을 물어봐요","role":"점원 (Clerk)","open":"Hi! May I help you?","turns":3,"script":[{"ai":"They're thirteen thousand won."},{"ai":"It's ten thousand won."},{"ai":"Have a nice day!"}],"hints":["Yes, please. How much are these sunglasses?","How much is this hat?","Thank you."]}},{"lesson":6,"pos":7,"n":2,"kind":"aitalk","tag":"speak","payload":{"tag":"speak","k":"aitalk","situation":"재킷 가게에서 값을 물어봐요","role":"점원 (Clerk)","open":"Hello! May I help you?","turns":3,"script":[{"ai":"It's thirty thousand won."},{"ai":"They're fifteen thousand won."},{"ai":"Thank you! Come again!"}],"hints":["Yes, please. How much is this jacket?","How much are these shorts?","Thank you."]}}]$j$::jsonb) as x(lesson int, pos int, n int, kind text, tag text, payload jsonb);

  select count(*) into v_miss from _l9 d where not exists (
    select 1 from flow_steps s join flow_lessons fl on fl.id = s.lesson_id where fl.unit_id = v_unit and fl.no = d.lesson and s.pos = d.pos and s.kind = d.kind);
  if v_miss > 0 then raise exception 'L9 content: % item(s) do not match a template step (lesson/pos/kind)', v_miss; end if;

  insert into items(unit_id, lesson, act_idx, level, template, tag, payload, status, step_id, created_at)
  select v_unit, d.lesson, d.pos, 'CORE', d.kind, d.tag, d.payload, 'draft', s.id, now() + (d.n * interval '1 millisecond')
    from _l9 d join flow_lessons fl on fl.unit_id = v_unit and fl.no = d.lesson join flow_steps s on s.lesson_id = fl.id and s.pos = d.pos;
  get diagnostics v_n = row_count;
  if v_n <> (select count(*) from _l9) then raise exception 'L9 content: inserted % of %', v_n, (select count(*) from _l9); end if;
end $do$;
